import{_ as i,c as a,o as t,ag as e}from"./chunks/framework.3IuuWm4t.js";const c=JSON.parse('{"title":"WordPress 配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/wordpress-wordpress.md","filePath":"platforms/wordpress-wordpress.md","lastUpdated":1795809563000}'),r={name:"platforms/wordpress-wordpress.md"};function n(d,s,l,o,p,h){return t(),a("div",null,[...s[0]||(s[0]=[e(`<h1 id="wordpress-配置指南" tabindex="-1">WordPress 配置指南 <a class="header-anchor" href="#wordpress-配置指南" aria-label="Permalink to &quot;WordPress 配置指南&quot;">​</a></h1><p>通过 <strong>XML-RPC</strong> 发布到自建/托管 WordPress。</p><h2 id="一、准备" tabindex="-1">一、准备 <a class="header-anchor" href="#一、准备" aria-label="Permalink to &quot;一、准备&quot;">​</a></h2><ol><li>一个 WordPress 站点（含管理员账号）。</li><li>一个 <strong>应用程序密码</strong>（Application Password，推荐；也可用账号密码）。</li></ol><h2 id="二、获取应用程序密码" tabindex="-1">二、获取应用程序密码 <a class="header-anchor" href="#二、获取应用程序密码" aria-label="Permalink to &quot;二、获取应用程序密码&quot;">​</a></h2><p>WordPress 后台 → 用户 → 编辑 → 滚动到「应用程序密码」→ 生成。地址：<code>https://你的站点/wp-admin/profile.php</code></p><h2 id="三、配置" tabindex="-1">三、配置 <a class="header-anchor" href="#三、配置" aria-label="Permalink to &quot;三、配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>平台首页</td><td>站点首页，如 <code>https://yourblog.com</code></td></tr><tr><td>API 地址</td><td>通常自动推导为 <code>https://yourblog.com/xmlrpc.php</code></td></tr><tr><td>用户名</td><td>WordPress 管理员用户名</td></tr><tr><td>密码</td><td>账号密码；建议用后台生成的<strong>应用程序密码</strong></td></tr><tr><td>预览规则</td><td>默认 <code>/?p=[postid]</code>，与默认固定链接一致，一般不改</td></tr><tr><td>发布格式</td><td>默认 <strong>HTML</strong>（插件先把笔记转成 HTML 再提交）；选 Markdown 则提交 Markdown 原文</td></tr><tr><td>图床服务</td><td>默认「当前平台」：经 XML-RPC 上传到 WordPress 媒体库；也可改选「PicGo 强烈推荐」用你配置的 PicGo；「不使用」跳过图片处理、按原图地址引用（需公网可访问）</td></tr></tbody></table><h2 id="四、验证与发布" tabindex="-1">四、验证与发布 <a class="header-anchor" href="#四、验证与发布" aria-label="Permalink to &quot;四、验证与发布&quot;">​</a></h2><ol><li>点「验证」→ 通过后保存。</li><li>快速发布 → 选 WordPress → 发布。</li></ol><h2 id="五、特色图片" tabindex="-1">五、特色图片 <a class="header-anchor" href="#五、特色图片" aria-label="Permalink to &quot;五、特色图片&quot;">​</a></h2><p>发布页切到「详细模式」后有「特色图片」一栏（仅 WordPress 支持），三种填写方式任选：</p><ul><li><strong>上传图片</strong>：从本机选一张图片，插件先存进思源资源库（<code>assets/</code>），发布时再随文章上传到 WordPress 媒体库；</li><li><strong>取正文首图</strong>：直接引用正文第一张图片；</li><li>手动填思源资源相对路径（如 <code>assets/cover.png</code>）或完整图片链接。</li></ul><p>无论哪种方式，图片都会先上传到 WordPress 媒体库，再设为该文章的<strong>特写图（Featured Image）</strong>。</p><p>设置会被记在文档的 WordPress 平台属性里（<code>featured_image</code>），下次打开发布页会自动回填；清空后重新发布会移除已设置的特写图。</p><h2 id="六、思源文档-id-siyuanid" tabindex="-1">六、思源文档 ID（siyuanid） <a class="header-anchor" href="#六、思源文档-id-siyuanid" aria-label="Permalink to &quot;六、思源文档 ID（siyuanid）&quot;">​</a></h2><p>发布到自建 WordPress 时，插件会把<strong>来源思源文档 ID</strong> 写入文章的 <code>siyuanid</code> 自定义字段（post meta），方便外部工具把 WordPress 文章和思源文档对应起来。</p><ul><li><strong>新建文章</strong>：随 <code>metaWeblog.newPost</code> 创建该字段。</li><li><strong>再次发布/更新</strong>：读取文章已有的 <code>custom_fields</code>，按已有 meta 的 <code>id</code> 原地更新；不会重复添加同名字段，也不会改动其他自定义字段。</li><li><strong>没有来源文档 ID 时</strong>：不写入该字段，不会伪造空值。</li><li><strong>权限要求</strong>：账号需要有编辑文章和 post meta 的权限；XML-RPC 需开启（与发布本身的要求一致）。</li><li><strong>WordPress.com</strong>：走独立的适配器，不写入该字段。</li></ul><p>读取方式（WordPress 侧）：</p><div class="language-php vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$siyuanId </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> get_post_meta</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($post_id, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;siyuanid&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>如果需要在 REST API 响应里看到 <code>meta.siyuanid</code>，需要在 WordPress 侧注册该 meta：</p><div class="language-php vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">register_post_meta</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;post&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;siyuanid&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;type&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;string&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;single&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;show_in_rest&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><blockquote><p>该字段只用于<strong>关联来源文档</strong>，本身不会自动去重、查找既有文章或阻止重复发布；这些需要额外的匹配/唯一性逻辑。</p></blockquote><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>XML-RPC 被禁用</strong>：检查 WordPress 是否开启 XML-RPC，安全插件是否拦截 <code>/xmlrpc.php</code>。</li><li><strong>应用程序密码在哪</strong>：后台 → 用户 → 编辑 → 应用程序密码 → 生成。</li><li><strong>图片上传失败</strong>：确认「图床服务」选的是「当前平台」（经 XML-RPC 上传到 WordPress 媒体库）、站点媒体库权限和网络连通；也可改用「PicGo 强烈推荐」。</li></ul>`,25)])])}const g=i(r,[["render",n]]);export{c as __pageData,g as default};
